دالة عدّ_الحرف(نص، حرف) {
    متغير عد = ٠
    من_أجل (ي من ٠ إلى طول(نص) - ١) {
        إذا (نص[ي] == حرف) {
            عد = عد + ١
        }
    }
    ارجع عد
}
